import{_ as a,o as s,c as t,as as i}from"./chunks/framework.B8NLttm5.js";const u=JSON.parse('{"title":"手册维护与覆盖检查","description":"","frontmatter":{},"headers":[],"relativePath":"guide/docs-maintenance.md","filePath":"guide/docs-maintenance.md"}'),n={name:"guide/docs-maintenance.md"};function o(d,e,c,r,p,l){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="手册维护与覆盖检查" tabindex="-1">手册维护与覆盖检查 <a class="header-anchor" href="#手册维护与覆盖检查" aria-label="Permalink to &quot;手册维护与覆盖检查&quot;">​</a></h1><h2 id="更新组件后" tabindex="-1">更新组件后 <a class="header-anchor" href="#更新组件后" aria-label="Permalink to &quot;更新组件后&quot;">​</a></h2><p>在组件库仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:generate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span></code></pre></div><p>生成工具遍历包入口的公开 SFC 导出，包含子组件、流程节点和配置面板；从源码抽取 Props、默认值、事件、插槽和公开实例成员。场景页中的 generated-api 标记区也由同一工具更新，请将场景说明放在标记外。</p><p>手册构建会先执行覆盖校验。新增导出、修改 API 或遗留多余生成页都会导致检查失败，运行生成命令后再构建。源码无法解析的 Props 类型会直接报错，避免生成空表掩盖遗漏。</p><h2 id="样式与交互" tabindex="-1">样式与交互 <a class="header-anchor" href="#样式与交互" aria-label="Permalink to &quot;样式与交互&quot;">​</a></h2><p>真实组件放在 vp-raw 演示区，隔离 VitePress 正文排版。新增演示应同时检查：明暗主题、窄屏溢出、空数据、禁用状态、双向绑定、展开层与复制代码。依赖 DOM 或挂载后注册子项的演示使用 ClientOnly。</p><h2 id="发布" tabindex="-1">发布 <a class="header-anchor" href="#发布" aria-label="Permalink to &quot;发布&quot;">​</a></h2><p>源码构建产物位于 ecosystem/docs/.vitepress/dist。公开 GitHub 仓库保存发布产物；维护源代码后重新构建，再使用增量提交更新公开站点，保留历史记录。文档改动不需要调整 npm 组件版本。</p><h2 id="演示渲染检查" tabindex="-1">演示渲染检查 <a class="header-anchor" href="#演示渲染检查" aria-label="Permalink to &quot;演示渲染检查&quot;">​</a></h2><p><code>docs:check</code> 和手册构建同时校验示例组件注册名，按 Vue 实际大小写解析规则检查 <code>x-*</code> / <code>P*</code>，包括 QRCode 这类缩写。它还会检查本地图片资源是否存在、排除外部占位图片，以及移动预览的功能入口与插槽是否对应。</p><p>演示图片放在 <code>public/demo</code>，在线模板和数据通过 VitePress 的 <code>withBase()</code> 生成路径；不要直接依赖随机图片站或无效占位域名。故意展示图片加载失败的示例需提供可见错误状态。</p>`,13)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
